function PTTK_Show(msg)
	Msg2Player(msg)
	Say(msg, 1, "\167\227ng/no_pttk")
end

function PTTK_Log(tag)
	if openfile == nil or date == nil then return end
	local fh = openfile("admin_bridge\\token.log", "a")
	if fh then
		write(fh, date("%Y-%m-%d %H:%M:%S") .. "\tthanky\t" .. tag .. "\n")
		closefile(fh)
	end
end

-- ---------------------------------------------------------------- Than Ky books
-- cap 1..4: learn / raise the skill to that level; cap 5: raise to 5, then each further book +1 level (max 10).
-- The book is removed only when GetMagicLevel confirms the new level.
function PTTK_UseBook(nItemIdx, sk, cap)
	local s = PTTK_SKILL[sk]
	if s == nil then
		PTTK_Show("Kh\171ng nh\203n ra Th\199n K\252 n\181y.")
		return 0
	end
	local prof = GetProfession()
	local cur = HaveMagic(sk)
	if cur == nil then cur = -1 end
	PTTK_Log("book skill=" .. sk .. " cap=" .. cap .. " prof=" .. (prof or -9) .. " lv=" .. (GetLevel() or -9) .. " have=" .. cur)
	if prof ~= s[1] then
		PTTK_Show("Th\199n K\252 " .. s[2] .. " ch\216 d\181nh cho ph\184i " .. PTTK_PROF[s[1]] .. ".")
		return 0
	end
	if GetLevel() < PTTK_REQ_LEVEL then
		PTTK_Show("C\199n \174\185t c\202p " .. PTTK_REQ_LEVEL .. " m\237i l\220nh h\233i \174\173\238c Th\199n K\252 " .. s[2] .. ".")
		return 0
	end
	local target = cap
	if cap >= PTTK_BOOK_MAX and cur >= PTTK_BOOK_MAX then target = cur + 1 end
	if target > PTTK_MAX_LEVEL then
		PTTK_Show(s[2] .. " \174\183 \174\185t c\202p t\232i \174a " .. PTTK_MAX_LEVEL .. ", s\184ch v\201n c\223n.")
		return 0
	end
	if cur >= target then
		PTTK_Show("Ng\173\172i \174\183 l\220nh h\233i " .. s[2] .. " c\202p " .. cur .. ", s\184ch c\202p " .. cap .. " kh\171ng c\223n t\184c d\244ng. S\184ch v\201n c\223n; d\239ng s\184ch c\202p cao h\172n.")
		return 0
	end
	AddMagic(sk, target)
	local nl = GetMagicLevel(sk)
	if nl == nil or nl < target then
		PTTK_Log("book FAIL skill=" .. sk .. " target=" .. target .. " now=" .. (nl or -9))
		PTTK_Show("L\220nh h\233i th\202t b\185i, s\184ch v\201n c\223n.")
		return 0
	end
	RemoveItem(nItemIdx, 1, 0)
	PTTK_Log("book ok skill=" .. sk .. " level=" .. nl)
	if cur < 1 then
		PTTK_Show("\167\183 l\220nh h\233i Th\199n K\252 " .. s[2] .. " c\202p " .. nl .. ". M\235 \171 k\252 n\168ng chu\233t (tr\184i/ph\182i) \174\211 ch\228n v\181 s\246 d\244ng.")
	else
		PTTK_Show("Th\199n K\252 " .. s[2] .. " t\168ng l\170n c\202p " .. nl .. ".")
	end
	return 0
end

-- ---------------------------------------------------------------- Manh Than Ky (stack 250): PTTK_MANH_NEED pieces of one
-- stack -> the next useful book (not learned: cap 1; learned at level L: cap L+1, at most cap 5; other profession: cap 1).
function PTTK_UseManh(nItemIdx)
	local key = GetItemPartByID(nItemIdx)
	local sk = PTTK_MANH[key]
	if sk == nil then
		PTTK_Show("Kh\171ng nh\203n ra m\182nh Th\199n K\252 n\181y.")
		return 0
	end
	local s = PTTK_SKILL[sk]
	local have = GetStackItem(nItemIdx)
	if have == nil or have < 1 then have = 1 end
	PTTK_Log("manh key=" .. key .. " stack=" .. have)
	if have < PTTK_MANH_NEED then
		PTTK_Show("C\199n " .. PTTK_MANH_NEED .. " M\182nh Th\199n K\252 " .. s[2] .. " trong c\239ng m\233t ch\229ng \174\211 gh\208p (ch\229ng n\181y c\227 " .. have .. "). G\233p c\184c m\182nh v\181o m\233t ch\229ng r\229i nh\202p ph\182i l\185i.")
		return 0
	end
	if CalcFreeItemCellCount(1, 1) < 1 then
		PTTK_Show("H\181nh trang c\199n \221t nh\202t 1 \171 tr\232ng \174\211 gh\208p Th\199n K\252.")
		return 0
	end
	local cur = -1
	if GetProfession() == s[1] then
		cur = HaveMagic(sk)
		if cur == nil then cur = -1 end
	end
	local cap = 1
	if cur >= 1 then cap = cur + 1 end
	if cap > PTTK_BOOK_MAX then cap = PTTK_BOOK_MAX end
	local bk = PTTK_BOOKKEY[sk][cap]
	if AddNormalItem(6, 1, bk, 1, 0, 0) <= 0 then
		PTTK_Show("Kh\171ng th\170m \174\173\238c s\184ch v\181o h\181nh trang, m\182nh v\201n c\223n.")
		return 0
	end
	RemoveItem(nItemIdx, PTTK_MANH_NEED, 0)
	PTTK_Log("manh ok skill=" .. sk .. " book=" .. bk .. " cap=" .. cap)
	PTTK_Show("Gh\208p " .. PTTK_MANH_NEED .. " m\182nh th\181nh Th\199n K\252 " .. s[2] .. " c\202p " .. cap .. ". Nh\202p ph\182i v\181o s\184ch \174\211 l\220nh h\233i.")
	return 0
end

-- ---------------------------------------------------------------- Vien Thuoc Tinh: permanent base points (saved with the
-- character), at most PTTK_STONE_CAP points per stat from stones (tasks PTTK_T_STAT). The free points do not change:
-- AddProp(n) first, then AddStrg/AddEng/AddVit/AddDex(n) (which subtract n free points, ScriptFuns.cpp).
function PTTK_GetStat(st)
	if st == 1 then return GetStrg(1) or 0 end
	if st == 2 then return GetEng(1) or 0 end
	if st == 3 then return GetVit(1) or 0 end
	return GetDex(1) or 0
end

function PTTK_AddStat(st, n)
	if st == 1 then AddStrg(n) elseif st == 2 then AddEng(n) elseif st == 3 then AddVit(n) else AddDex(n) end
end

function PTTK_UseStone(nItemIdx, st, tier)
	local t = PTTK_T_STAT[st]
	if t == nil or PTTK_TIER_AMOUNT[tier] == nil then return 0 end
	local used = GetTask(t) or 0
	local room = PTTK_STONE_CAP - used
	if room <= 0 then
		PTTK_Show("\167\183 c\233ng t\232i \174a " .. PTTK_STONE_CAP .. " \174i\211m " .. PTTK_STAT_NAME[st] .. " t\245 Vi\170n Thu\233c T\221nh. Vi\170n v\201n c\223n.")
		return 0
	end
	local n = PTTK_TIER_AMOUNT[tier]
	if n > room then n = room end
	local before = PTTK_GetStat(st)
	local free0 = GetProp() or 0
	AddProp(n)
	PTTK_AddStat(st, n)
	local after = PTTK_GetStat(st)
	if after < before + n then
		AddProp(free0 - (GetProp() or 0))      -- put the free points back as they were
		PTTK_Log("stone FAIL stat=" .. st .. " before=" .. before .. " after=" .. after)
		PTTK_Show("D\239ng Vi\170n Thu\233c T\221nh th\202t b\185i, vi\170n v\201n c\223n.")
		return 0
	end
	SetTask(t, used + n)
	RemoveItem(nItemIdx, 1, 0)
	PTTK_Log("stone ok stat=" .. st .. " +" .. n .. " used=" .. (used + n) .. " base=" .. after)
	PTTK_Show(PTTK_STAT_NAME[st] .. " +" .. n .. " (" .. PTTK_STAT_F3[st] .. " g\232c " .. after .. "). \167\183 c\233ng t\245 vi\170n: " .. (used + n) .. "/" .. PTTK_STONE_CAP .. ".")
	return 0
end

-- Tui Thuoc Tinh: one random stone (weighted tier, random stat).
function PTTK_OpenBag(nItemIdx, key)
	local b = PTTK_BAG[key]
	if b == nil then return 0 end
	if CalcFreeItemCellCount(1, 1) < 1 then
		PTTK_Show("H\181nh trang c\199n \221t nh\202t 1 \171 tr\232ng \174\211 m\235 t\243i.")
		return 0
	end
	local tot = 0
	local i = 1
	while b[i] do tot = tot + b[i][1] i = i + 1 end
	local r = random(1, tot)
	local tier = b[1][2]
	i = 1
	while b[i] do
		if r <= b[i][1] then tier = b[i][2] break end
		r = r - b[i][1]
		i = i + 1
	end
	local st = random(1, 4)
	local sk = PTTK_STONE_KEY[st][tier]
	if AddNormalItem(6, 1, sk, 1, 0, 0) <= 0 then
		PTTK_Show("Kh\171ng th\170m \174\173\238c Vi\170n Thu\233c T\221nh v\181o h\181nh trang, t\243i v\201n c\223n.")
		return 0
	end
	RemoveItem(nItemIdx, 1, 0)
	PTTK_Log("bag ok key=" .. key .. " stone=" .. sk)
	PTTK_Show("M\235 " .. PTTK_BAG_NAME[key] .. " nh\203n \174\173\238c Vi\170n " .. PTTK_STAT_NAME[st] .. "-" .. PTTK_TIER_NAME[tier] .. " (+" .. PTTK_TIER_AMOUNT[tier] .. " " .. PTTK_STAT_NAME[st] .. "). Nh\202p ph\182i v\181o vi\170n \174\211 d\239ng.")
	return 0
end
